{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (args.length === 1 && (mode === 'waves' || mode === 'explain')) {
  // ok
} else if (args.length === 2 && mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail('error: usage: cli.js waves|explain|pack <workers>')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depLines = []
const nameRe = /^[A-Za-z0-9_.-]+$/
lines.forEach((raw, i) => {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!nameRe.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})

for (const names of depLines) {
  for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
  if (!deps.has(names[0])) deps.set(names[0], new Set())
  for (const d of names.slice(1)) deps.get(names[0]).add(d)
}
const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((n) => [n, [...(deps.get(n) || [])].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const c = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + c.join(' -> '), 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const n of names) if (!state.get(n)) visit(n)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0
  let d = 0
  for (const v of dl.get(u)) {
    calc(v)
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
names.forEach(calc)
const total = names.reduce((m, n) => Math.max(m, finish.get(n)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const n of names) (ws[depth.get(n)] ||= []).push(n)
  ws.forEach((w, k) => (out += `wave ${k}: ${w.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const n of names) out += `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const rev = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of dl.get(n)) rev.get(d).push(n)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of rev.get(u)) m = Math.max(m, pr(v))
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => prio.get(b) - prio.get(a) || cmp(a, b))
  const done = new Map()
  const freeAt = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  let remaining = order.slice()
  let t = 0
  let makespan = 0
  while (remaining.length) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const idx = remaining.findIndex((u) => dl.get(u).every((d) => done.has(d) && done.get(d) <= t))
      if (idx < 0) break
      const u = remaining.splice(idx, 1)[0]
      const f = t + cost.get(u)
      done.set(u, f)
      freeAt[wi] = f
      ran[wi].push(`${u}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (!remaining.length) break
    const next = Math.min(
      ...freeAt.filter((f) => f > t),
      ...[...done.values()].filter((f) => f > t),
    )
    t = next
  }
  ran.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
node --test test/*.test.js 2>&1 | grep -E "^# (pass|fail)"","description":"Write cli and run tests"}

