import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0).toString('utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
cat > src/scanner.js <<'EOF'
export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (i, reason) => { throw new ScanError(lines[i], cols[i], reason) }
  const tokens = []
  const push = (i, kind, body) => tokens.push({ line: lines[i], col: cols[i], kind, body })

  // consume a run of digits (per `ok`) with single underscores between digits
  const run = (i, ok) => {
    while (i < n) {
      if (ok(cs[i])) i++
      else if (cs[i] === '_' && i > 0 && ok(cs[i - 1]) && ok(cs[i + 1])) i++
      else break
    }
    return i
  }

  let i = 0
  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) fail(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i
      while (j < n && isIdChar(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(i, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      let bad = false
      const p = (cs[i + 1] || '').toLowerCase()
      if (ch === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const ok = p === 'x' ? isHex : p === 'b' ? isBin : isOct
        j = i + 2
        if (!ok(cs[j])) bad = true
        else j = run(j, ok)
      } else {
        j = run(j, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (bad || isIdChar(cs[j])) {
        while (j < n && isIdChar(cs[j])) j++
        fail(i, `invalid number ${cs.slice(i, j).join('')}`)
      }
      push(i, 'number', cs.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let val = ''
      for (;;) {
        if (j >= n) fail(i, 'unterminated string')
        const d = cs[j]
        if (d === '"') break
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') { val += d; j++; continue }
        if (j + 1 >= n) fail(i, 'unterminated string')
        const e = cs[j + 1]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { val += simple[e]; j += 2 }
        else if (e === 'x') {
          if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
            val += String.fromCharCode(parseInt(cs[j + 2] + cs[j + 3], 16))
            j += 4
          } else fail(j, 'invalid escape \\x')
        } else if (e === 'u') {
          let k = j + 2
          let ok = cs[k] === '{'
          let hex = ''
          if (ok) {
            k++
            while (isHex(cs[k])) hex += cs[k++]
            ok = hex.length > 0 && cs[k] === '}' && parseInt(hex, 16) <= 0x10ffff
          }
          if (!ok) fail(j, 'invalid escape \\u')
          val += String.fromCodePoint(parseInt(hex, 16))
          j = k + 1
        } else fail(j, `invalid escape \\${e}`)
      }
      push(i, 'string', JSON.stringify(val))
      i = j + 1
      continue
    }
    const two = ch + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { push(i, 'punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { push(i, 'punct', ch); i++; continue }
    fail(i, `unexpected character ${ch}`)
  }
  return tokens
}
