function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs, mode) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const sides = [mine, theirs]
  const out = []
  let conflict = false
  const regions = []
  let pos = 0
  const stable = to => {
    if (to > pos) {
      out.push(...base.slice(pos, to))
      regions.push(`stable ${to - pos}`)
    }
  }
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    const baseLines = base.slice(rs, re)
    const rep = sides.map((lines, s) => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseLines
      const first = cs[0], last = cs[cs.length - 1]
      const smin = Math.min(...cs.map(c => c.bs)), smax = Math.max(...cs.map(c => c.be))
      return lines.slice(first.ss - (smin - rs), last.se + (re - smax))
    })
    const [m, t] = rep
    if (eq(m, t)) { out.push(...m); regions.push(`both ${m.length}`) }
    else if (eq(m, baseLines)) { out.push(...t); regions.push(`theirs ${t.length}`) }
    else if (eq(t, baseLines)) { out.push(...m); regions.push(`mine ${m.length}`) }
    else {
      conflict = true
      out.push('<<<<<<< mine', ...m)
      if (mode !== 'merge2') out.push('||||||| base', ...baseLines)
      out.push('=======', ...t, '>>>>>>> theirs')
      regions.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
    }
    pos = re
  }
  stable(base.length)
  return { out: mode === 'regions' ? regions : out, conflict }
}
