#!/usr/bin/env node
import { parse, normalize, resolve, checkPercent } from './uri.js'
import fs from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}
const mode = args[0]
const lines = fs.readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const out = []
lines.forEach((line, i) => {
  const n = i + 1
  let target
  if (mode === 'normalize') {
    target = parse(line)
  } else {
    const sp = line.indexOf(' ')
    if (sp < 0) fail(`line ${n}: expected a base and a reference`)
    const base = parse(line.slice(0, sp))
    if (base.scheme === null) fail(`line ${n}: the base has no scheme`)
    target = resolve(base, parse(line.slice(sp + 1)))
  }
  const bad = checkPercent(target)
  if (bad) fail(`line ${n}: the ${bad} has a truncated percent-encoding`)
  out.push(normalize(target))
})
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
cat > src/uri.js <<'EOF'
export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    m = /^\/\/[^/?#]*/.exec(s)
    r.authority = m[0].slice(2)
    s = s.slice(m[0].length)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const rest = a.slice(at + 1)
  const rb = rest.lastIndexOf(']')
  const c = rest.indexOf(':', rb + 1)
  if (c < 0) return { userinfo, host: rest, port: null }
  return { userinfo, host: rest.slice(0, c), port: rest.slice(c + 1) }
}

const bad = (s) => s !== null && /%(?![0-9A-Fa-f]{2})|%[0-9A-Fa-f](?![0-9A-Fa-f])/.test(s)

export function checkPercent(t) {
