export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  const num = (n, field, v, least) => {
    if (!COUNT.test(v) || BigInt(v) < BigInt(least)) {
      throw new ParseError(n, `${field} must be an integer of at least ${least}`)
    }
    return BigInt(v)
  }
  const name = (n, v) => {
    if (!WORD.test(v)) throw new ParseError(n, `invalid policy name ${v}`)
  }

  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const d = t[0]
    if (d !== 'bucket' && d !== 'window' && d !== 'route' && d !== 'event') {
      throw new ParseError(n, `unknown directive ${d}`)
    }
    if (d !== 'event' && events.length > 0) {
      throw new ParseError(n, 'declarations must come before the first event')
    }
    if (d === 'bucket') {
      if (t.length !== 5) throw new ParseError(n, 'expected bucket <name> <capacity> <refill> <per>')
      name(n, t[1])
      const capacity = num(n, 'capacity', t[2], 1)
      const refill = num(n, 'refill', t[3], 0)
      const per = num(n, 'per', t[4], 1)
      if (policies.has(t[1])) throw new ParseError(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
    } else if (d === 'window') {
      if (t.length !== 4) throw new ParseError(n, 'expected window <name> <limit> <span>')
      name(n, t[1])
      const limit = num(n, 'limit', t[2], 0)
      const span = num(n, 'span', t[3], 1)
      if (policies.has(t[1])) throw new ParseError(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'window', name: t[1], limit, span })
    } else if (d === 'route') {
      if (t.length < 3) throw new ParseError(n, 'expected route <prefix> <policy>...')
      if (!WORD.test(t[1])) throw new ParseError(n, `invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) throw new ParseError(n, `prefix ${t[1]} is routed twice`)
      const list = t.slice(2).map((p) => {
        if (!policies.has(p)) throw new ParseError(n, `unknown policy ${p}`)
        return policies.get(p)
      })
      routes.set(t[1], list)
    } else {
      if (t.length !== 3) throw new ParseError(n, 'expected event <tick> <key>')
      const tick = num(n, 'tick', t[1], 0)
      if (!WORD.test(t[2])) throw new ParseError(n, `invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(n, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key: t[2] })
    }
  })
  return { routes, events }
