// Bucket tokens are stored as integer units of 1/per token, so refills stay exact.
function makeState(p, tick) {
  if (p.kind === 'bucket') {
    return { units: p.capacity * p.per, last: tick }
  }
  return { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const cap = p.capacity * p.per
    s.units += p.refill * (tick - s.last)
    if (s.units > cap) s.units = cap
    s.last = tick
  } else {
    const cutoff = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cutoff)
  }
}

function allows(p, s) {
  return p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, s, tick) {
  if (p.kind === 'bucket') s.units -= p.per
  else s.ticks.push(tick)
}

export function simulate({ routes, events }, mode) {
  const prefixes = [...routes.keys()]
  const states = new Map()
  const stats = new Map()
  let out = ''
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) {
      if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    }
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const id = `${p.name}\0${key}`
        if (!states.has(id)) states.set(id, makeState(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < list.length; i++) {
        if (!allows(list[i], sts[i])) {
          denied = list[i].name
          break
        }
      }
      if (denied === null) list.forEach((p, i) => record(p, sts[i], tick))
    }
    const c = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, c)
    if (denied === null) { c.a++; ta++ } else { c.d++; td++ }
    if (mode === 'replay') out += `${tick} ${key} ${denied === null ? 'allow' : 'deny ' + denied}\n`
  }
  if (mode === 'summary') {
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
  return out
}
