import fs from 'node:fs'

const modes = ['merge', 'merge2', 'regions']
const args = process.argv.slice(2)
function fail(msg) { process.stderr.write(`error: ${msg}\n`); process.exit(2) }
if (args.length !== 1 || !modes.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
const mode = args[0]

let lines = fs.readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) { if (l === '%%%') docs.push([]); else docs[docs.length - 1].push(l) }
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

function changes(side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
    L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, ci = 0, cj = 0
  const flush = () => { if (i > ci || j > cj) out.push({ bs: ci, be: i, ss: cj, se: j, who }) }
  while (i < n && j < m) {
    if (base[i] === side[j]) { flush(); i++; j++; ci = i; cj = j }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const all = [...changes(mine, 0), ...changes(theirs, 1)].sort((a, b) => a.bs - b.bs || a.who - b.who)
const out = []
let conflict = false
const emitLines = (a) => { for (const l of a) out.push(l) }
let pos = 0
let k = 0
while (k < all.length) {
  const start = all[k].bs
  let end = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= end) { end = Math.max(end, all[k].be); group.push(all[k++]) }
  if (start > pos) {
    if (mode === 'regions') out.push(`stable ${start - pos}`); else emitLines(base.slice(pos, start))
  }
  pos = end
  const baseL = base.slice(start, end)
  const sideL = (side, who) => {
    const g = group.filter(c => c.who === who)
    if (!g.length) return baseL
    const ms = Math.min(...g.map(c => c.ss)), bsm = Math.min(...g.map(c => c.bs))
    const me = Math.max(...g.map(c => c.se)), bem = Math.max(...g.map(c => c.be))
    return side.slice(ms - (bsm - start), me + (end - bem))
  }
  const m = sideL(mine, 0), t = sideL(theirs, 1)
  const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
  let kind, res
  if (eq(m, t)) { kind = 'both'; res = m }
  else if (eq(m, baseL)) { kind = 'theirs'; res = t }
  else if (eq(t, baseL)) { kind = 'mine'; res = m }
  else kind = 'conflict'
  if (kind === 'conflict') {
    conflict = true
    if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
    else {
      out.push('<<<<<<< mine'); emitLines(m)
      if (mode === 'merge') { out.push('||||||| base'); emitLines(baseL) }
      out.push('======='); emitLines(t); out.push('>>>>>>> theirs')
    }
  } else if (mode === 'regions') out.push(`${kind} ${res.length}`)
  else emitLines(res)
}
if (base.length > pos) {
  if (mode === 'regions') out.push(`stable ${base.length - pos}`); else emitLines(base.slice(pos))
}
process.stdout.write(out.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
