const NAME = /^[A-Za-z0-9_-]+$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (m) => { throw new Error(`line ${n}: ${m}`) }
    if (t[0] === 'candidates') {
      if (cands !== null) fail('candidates must be declared once, before any ballot')
      if (t.length < 2) fail('expected candidates <name>...')
      cands = []
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`invalid candidate name ${name}`)
        if (cands.includes(name)) fail(`candidate ${name} is declared twice`)
        cands.push(name)
      }
    } else if (t[0] === 'ballot') {
      if (cands === null) fail('candidates must be declared once, before any ballot')
      if (t.length < 3) fail('expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail('count must be a positive integer')
      const seen = []
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) fail(`unknown candidate ${name}`)
        if (seen.includes(name)) fail(`candidate ${name} is repeated`)
        seen.push(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: seen })
    } else {
      fail(`unknown directive ${t[0]}`)
    }
  }
  if (cands === null) throw new Error('no candidates')
  return { cands, ballots }
}
