export function count({ cands, ballots }) {
  const continuing = new Set(cands)
  const rounds = []
  const hist = new Map(cands.map((c) => [c, []]))
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    const round = { votes, exhausted: total - active, eliminated: null }
    rounds.push(round)
    for (const [c, v] of votes) hist.get(c).push(v)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of votes) if (v * 2n > active) return { rounds, winner: c }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let set = [...votes].filter(([, v]) => v === min).map(([c]) => c)
    outer: while (set.length > 1) {
      for (let r = 0; r < rounds.length; r++) {
        let lo = null, hi = null
        for (const c of set) {
          const v = hist.get(c)[r]
          if (lo === null || v < lo) lo = v
          if (hi === null || v > hi) hi = v
        }
        if (lo !== hi) { set = set.filter((c) => hist.get(c)[r] === lo); continue outer }
      }
      break
    }
    const out = set.reduce((a, b) => (a > b ? a : b))
    round.eliminated = out
    continuing.delete(out)
  }
}
