#!/usr/bin/env node
/**
 * `node src/cli.js rounds|tally` reads an election from standard input and
 * prints every round of the instant-runoff count, or only the round count.
 */
import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { count } from './count.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
let result
try {
  result = count(parse(readFileSync(0, 'utf8')))
} catch (e) {
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'rounds') {
  result.rounds.forEach((r, i) => {
    const list = [...r.votes].sort((a, b) => (a[1] === b[1] ? (a[0] < b[0] ? -1 : 1) : a[1] > b[1] ? -1 : 1))
    out += `round ${i + 1}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${r.exhausted}\n`
    if (r.eliminated !== null) out += `eliminated ${r.eliminated}\n`
  })
} else {
  out += `rounds ${result.rounds.length}\n`
}
out += result.winner === null ? 'no winner\n' : `winner ${result.winner}\n`
process.stdout.write(out)
