export class Table { constructor() { this.m = new Map(); this.hdr = false } }
export class Arr { constructor(aot) { this.items = []; this.aot = aot } }
export class Scal { constructor(t, v) { this.t = t; this.v = v } }

class ConfError extends Error {
  constructor(msg) { super(msg); this.confError = true }
}
const fail = (m) => { throw new ConfError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  /** True when at end of line or at a comment start. */
  eol() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  quoted() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === '"' && c === '\\') {
        const e = this.s[this.i]
        if (e === undefined) fail('unterminated string')
        this.i++
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else fail(`invalid escape \\${String.fromCodePoint(e.codePointAt(0))}`)
      } else out += c
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isNameCh(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; return parts }
    }
  }
  value(path, ctx) {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return new Scal('string', this.quoted())
    if (c === '[') return this.array(path, ctx)
    if (c === '{') return this.inline(path, ctx)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) {
      if (this.s[this.i] === '#' && this.i === st) break
      this.i++
    }
    const w = this.s.slice(st, this.i)
    if (w === '') fail('expected a value')
    if (w === 'true') return new Scal('boolean', true)
    if (w === 'false') return new Scal('boolean', false)
    if (INT.test(w)) return new Scal('integer', BigInt(w.replace(/_/g, '')))
    if (FLOAT.test(w)) return new Scal('float', Number(w.replace(/_/g, '')))
