      this.ws()
      if (this.eol()) fail('unterminated array')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') { this.i++; return arr }
      else fail('unterminated array')
    }
  }
  inline(path) {
    this.i++
    const t = new Table()
    this.ws()
    if (this.eol()) fail('unterminated inline table')
    if (this.s[this.i] === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.eol()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(path)
      assign(t, path, keys, v)
      this.ws()
      if (this.eol()) fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') { this.i++; return t }
      else fail('unterminated inline table')
    }
