  if (n instanceof Arr && n.aot) return [n.items[n.items.length - 1], p]
  return fail(`${p} is not a table`)
}

function assign(t, base, keys, v) {
  let p = base
  for (let j = 0; j < keys.length - 1; j++) [t, p] = walk(t, p, keys[j])
  const last = keys[keys.length - 1]
  const full = join(p, last)
  if (t.m.has(last)) fail(`key ${full} is defined twice`)
  t.m.set(last, v)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const lp = new LineParser(lines[n])
      lp.ws()
      if (lp.eol()) continue
      if (lp.s[lp.i] === '[') {
        const aot = lp.s[lp.i + 1] === '['
        lp.i += aot ? 2 : 1
        lp.ws()
        const keys = lp.dotted()
        lp.ws()
        for (let k = 0; k < (aot ? 2 : 1); k++) {
          if (lp.s[lp.i] !== ']') fail('unterminated table header')
          lp.i++
        }
        lp.ws()
        if (!lp.eol()) fail('trailing text after a table header')
        let t = root
        let p = ''
        for (let j = 0; j < keys.length - 1; j++) [t, p] = walk(t, p, keys[j])
        const last = keys[keys.length - 1]
        const full = join(p, last)
        const ex = t.m.get(last)
        if (aot) {
          if (ex === undefined) { const a = new Arr(true); t.m.set(last, a); cur = new Table(); a.items.push(cur) }
          else if (ex instanceof Arr && ex.aot) { cur = new Table(); ex.items.push(cur) }
          else fail(`${full} is not an array of tables`)
        } else {
          if (ex === undefined) { cur = new Table(); t.m.set(last, cur) }
          else if (ex instanceof Table) { cur = ex }
          else fail(`${full} is not a table`)
          if (cur.hdr) fail(`table ${full} is defined twice`)
          cur.hdr = true
        }
        curPath = full
        continue
      }
      const keys = lp.dotted()
      lp.ws()
      if (lp.s[lp.i] !== '=') fail('expected key = value')
      lp.i++
      lp.ws()
      const full = join(curPath, keys.join('.'))
      const v = lp.value(full)
      lp.ws()
      if (!lp.eol()) fail('trailing text after a value')
      assign(cur, curPath, keys, v)
    } catch (e) {
      if (e && e.confError) e.line = n + 1
      throw e
    }
  }
  return root
}
