  const run = (i, ok) => {
    while (ok(cs[i])) {
      i++
      while (cs[i] === '_' && ok(cs[i + 1])) i += 2
    }
    return i
  }

  let i = 0
  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw new ScanError(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cs[i + 1] === '"') {
      const start = i
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(start, 'unterminated string')
      push(start, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
