  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (names !== null || sawBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    names = []
    for (const nm of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) fail(`error: line ${n}: invalid candidate name ${nm}`)
      if (known.has(nm)) fail(`error: line ${n}: candidate ${nm} is declared twice`)
      known.add(nm); names.push(nm)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    sawBallot = true
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!known.has(nm)) fail(`error: line ${n}: unknown candidate ${nm}`)
      if (seen.has(nm)) fail(`error: line ${n}: candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = new Map(names.map((c) => [c, []]))
const out = []
let rounds = 0
let result
for (;;) {
  rounds++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n, exhausted = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c === undefined) exhausted += b.count
    else { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const order = [...counts.keys()].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  out.push(`round ${rounds}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${exhausted}`)
  if (active === 0n) { result = 'no winner'; break }
  const win = order.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) { result = `winner ${win}`; break }
  let cand = [...counts.keys()]
  for (let changed = true; changed && cand.length > 1;) {
    changed = false
    for (let r = 0; r < rounds; r++) {
      const vals = cand.map((c) => history.get(c)[r])
      const min = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some((v) => v !== min)) {
        cand = cand.filter((c) => history.get(c)[r] === min)
        changed = true
        break
      }
    }
  }
  const elim = cand.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
