#!/usr/bin/env node
/**
 * `node src/cli.js normalize|resolve` reads URI references from stdin, one
 * record per line, and prints one normalized result per line.
 */
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, checkPercent } from './uri.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'normalize' && mode !== 'resolve') {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const out = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i]
  const fail = (m) => {
    process.stderr.write(`error: line ${n}: ${m}\n`)
    process.exit(2)
  }
  let target
  if (mode === 'normalize') {
    target = parse(line)
  } else {
    const sp = line.indexOf(' ')
    if (sp < 0) fail('expected a base and a reference')
    const base = parse(line.slice(0, sp))
    if (base.scheme === undefined) fail('the base has no scheme')
    target = resolve(base, parse(line.slice(sp + 1)))
  }
  const bad = checkPercent(target)
  if (bad) fail(`the ${bad} has a truncated percent-encoding`)
  out.push(normalize(target))
}
process.stdout.write(out.map((l) => l + '\n').join(''))
