cat > src/uri.js <<'EOF'
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  const r = { scheme: m[1], path: m[3], query: m[4], fragment: m[5] }
  if (m[2] !== undefined) {
    let a = m[2]
    const at = a.lastIndexOf('@')
    if (at >= 0) {
      r.userinfo = a.slice(0, at)
      a = a.slice(at + 1)
    }
    const colon = a.indexOf(':', a.lastIndexOf(']') + 1)
    if (colon >= 0) {
      r.host = a.slice(0, colon)
      r.port = a.slice(colon + 1)
    } else {
      r.host = a
    }
    r.hasAuthority = true
  }
  return r
}

export function checkPercent(r) {
  const bad = (s) => s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)
  for (const k of ['path', 'userinfo', 'host', 'query', 'fragment']) if (bad(r[k])) return k
  return null
}

function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const j = inp.indexOf('/', 1)
      const seg = j < 0 ? inp : inp.slice(0, j)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref)
    t.path = removeDots(ref.path)
  } else if (ref.hasAuthority) {
    Object.assign(t, ref)
    t.scheme = base.scheme
    t.path = removeDots(ref.path)
  } else {
    const { scheme, hasAuthority, userinfo, host, port } = base
    Object.assign(t, { scheme, hasAuthority, userinfo, host, port })
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.hasAuthority && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
    }
  }
  return t
}

function pct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const up = h.toUpperCase()
    const c = String.fromCharCode(parseInt(up, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + up
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let s = ''
  if (scheme !== undefined) s += pct(scheme) === scheme ? scheme + ':' : scheme + ':'
  let path = pct(r.path)
  if (r.hasAuthority) {
    let a = ''
    if (r.userinfo !== undefined) a += pct(r.userinfo) + '@'
    a += lower(pct(r.host))
    let port = pct(r.port)
    if (port === '' || (scheme !== undefined && DEFAULT_PORTS[scheme] === port)) port = undefined
    if (port !== undefined) a += ':' + port
    s += '//' + a
  }
  path = removeDots(path)
  if (r.hasAuthority && path === '') path = '/'
  s += path
  if (r.query !== undefined) s += '?' + pct(r.query)
  if (r.fragment !== undefined) s += '#' + pct(r.fragment)
  return s
}
